const cards=[...document.querySelectorAll(".card")];
const modal=document.getElementById("modal"), body=document.getElementById("body");
function openModule(id){body.innerHTML=moduleBodies[id]||"<p>Guide not found.</p>";modal.classList.add("show");document.body.style.overflow="hidden";}
function closeModal(){modal.classList.remove("show");document.body.style.overflow="";}
cards.forEach(c=>c.addEventListener("click",()=>openModule(c.dataset.module)));
document.querySelectorAll(".diagram-card").forEach(c=>c.addEventListener("click",()=>openModule(c.dataset.module)));
document.getElementById("close").addEventListener("click",closeModal);
document.querySelector(".shade").addEventListener("click",closeModal);
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal();});
document.getElementById("theme").addEventListener("click",()=>document.body.classList.toggle("light"));

function filterCards(q){
 q=q.toLowerCase().trim();
 cards.forEach(c=>{c.style.display=(!q||c.innerText.toLowerCase().includes(q))?"block":"none";});
}
document.getElementById("topicSearch").addEventListener("input",e=>filterCards(e.target.value));

const sr=document.getElementById("syllabusResults");
function renderSyllabus(q=""){
 q=q.toLowerCase().trim();
 const list=syllabusTopics.filter(x=>!q||x.toLowerCase().includes(q)).slice(0,120);
 sr.innerHTML=list.map(x=>`<div class="syllabus-item"><b>FROM UPLOADED SYLLABUS</b>${x}</div>`).join("") || "<div class='callout'>No matching syllabus topic.</div>";
}
renderSyllabus();
document.getElementById("syllabusSearch").addEventListener("input",e=>renderSyllabus(e.target.value));
